#include "vring.h"
static void barrier(void){__atomic_thread_fence(__ATOMIC_SEQ_CST);}
int vq_init(struct vq*q,volatile void*base,uint16_t n){if(!q||!base||((uintptr_t)base&4095)||!n||n>VQ_MAX||(n&(n-1)))return 0;size_t off=((size_t)16*n+4+2*n+4095)&~(size_t)4095;if(off+4+8*n>VQ_BYTES)return 0;*q=(struct vq){.base=base,.n=n,.seen=0,.used_off=off};for(size_t i=0;i<VQ_BYTES;i++)q->base[i]=0;volatile uint16_t*a=(volatile uint16_t*)(q->base+16*n);a[0]=1;/* no interrupts */return 1;}
void vq_desc_set(struct vq*q,uint16_t id,uint64_t addr,uint32_t len,uint16_t flags){if(id>=q->n)return;volatile struct vq_desc*d=(volatile struct vq_desc*)q->base;d[id].addr=addr;d[id].len=len;d[id].flags=flags;d[id].next=0;}
int vq_submit(struct vq*q,uint16_t id){if(id>=q->n||q->pending[id])return 0;q->pending[id]=1;volatile uint16_t*a=(volatile uint16_t*)(q->base+16*q->n);uint16_t i=a[1];a[2+(i&(q->n-1))]=id;barrier();a[1]=(uint16_t)(i+1);barrier();return 1;}
int vq_pop(struct vq*q,struct vq_used*out){volatile uint16_t*u=(volatile uint16_t*)(q->base+q->used_off);uint16_t pending=(uint16_t)(u[1]-q->seen);if(!pending)return 0;if(pending>q->n)return -1;barrier();volatile struct vq_used*e=(volatile struct vq_used*)(q->base+q->used_off+4);uint32_t id=e[q->seen&(q->n-1)].id,len=e[q->seen&(q->n-1)].len;if(id>=q->n||!q->pending[id])return -1;q->pending[id]=0;*out=(struct vq_used){id,len};q->seen++;return 1;}
